// STOP PROGRESSION — the driver app's copy of fleet-management/stop_progress.py.
//
// ONE rule shared by the app (next stop, ETA, progress bar, Stops timeline) and
// the backend (stop visits, decision log). This file is a line-by-line port:
// same constants, same state shape (JSON-serialisable Map, so the app can
// persist it across process death), same decisions. Both implementations are
// checked against the SAME golden vectors (test/vectors.json, generated by
// fleet-management/tests/make_vectors.py): `dart run test/vectors_test.dart`.
// Change one side only together with the other and regenerate the vectors.
//
// Module-agnostic: no School / University branching.

import 'dart:math' as math;

const int stopProgressVersion = 1;

const Map<String, num> stopProgressDefaults = {
  'arrive_radius_m': 60.0,
  'exit_hysteresis_m': 40.0,
  'exit_fixes': 2,
  'pass_radius_m': 150.0,
  'away_m': 100.0,
  'away_fixes': 2,
  'stop_dwell_s': 20.0,
  'stopped_mps': 1.5,
  'lookahead': 2,
  'max_interp_gap_s': 60.0,
  'road_factor': 1.25,
  'min_eta_speed_mps': 5.0,
  'near_radius_m': 300.0,
  'near_dwell_s': 60.0,
  'near_moving_mps': 3.0,
};

/// Effective config. Only arrive_radius_m is org-configurable (25..300 m);
/// the pass radius follows it (>= 2.5 x radius, never below 150 m).
Map<String, double> stopProgressConfig([Map<String, dynamic>? overrides]) {
  final cfg = stopProgressDefaults.map((k, v) => MapEntry(k, v.toDouble()));
  final r = overrides?['arrive_radius_m'];
  if (r is num) cfg['arrive_radius_m'] = math.min(300.0, math.max(25.0, r.toDouble()));
  cfg['pass_radius_m'] = math.max(stopProgressDefaults['pass_radius_m']!.toDouble(), 2.5 * cfg['arrive_radius_m']!);
  return cfg;
}

// ── geometry ────────────────────────────────────────────────────────────────

double _rad(double d) => d * math.pi / 180.0;

double haversineM(double lat1, double lng1, double lat2, double lng2) {
  const r = 6371000.0;
  final p1 = _rad(lat1), p2 = _rad(lat2);
  final dp = p2 - p1, dl = _rad(lng2 - lng1);
  final a = math.pow(math.sin(dp / 2), 2) + math.cos(p1) * math.cos(p2) * math.pow(math.sin(dl / 2), 2);
  return 2 * r * math.asin(math.min(1.0, math.sqrt(a)));
}

/// (distance m, fraction 0..1) of the closest point to `s` on segment a->b.
List<double> closestOnSegment(Map a, Map b, Map s) {
  const k = 111320.0;
  final c = math.cos(_rad((s['lat'] as num).toDouble()));
  final slat = (s['lat'] as num).toDouble(), slng = (s['lng'] as num).toDouble();
  final ax = ((a['lng'] as num) - slng) * k * c, ay = ((a['lat'] as num) - slat) * k;
  final bx = ((b['lng'] as num) - slng) * k * c, by = ((b['lat'] as num) - slat) * k;
  final dx = bx - ax, dy = by - ay;
  final l2 = dx * dx + dy * dy;
  final t = l2 == 0 ? 0.0 : math.max(0.0, math.min(1.0, -(ax * dx + ay * dy) / l2));
  final x = ax + t * dx, y = ay + t * dy;
  return [math.sqrt(x * x + y * y), t];
}

DateTime _parse(Object t) => t is DateTime ? t.toUtc() : DateTime.parse(t as String).toUtc();
String _iso(DateTime d) => d.toUtc().toIso8601String();
double? _r1(num? x) => x == null ? null : (x * 10).round() / 10.0;
double _secs(DateTime a, DateTime b) => a.difference(b).inMicroseconds / 1e6;

// ── state ───────────────────────────────────────────────────────────────────

Map<String, dynamic> newProgressState() => {
      'v': stopProgressVersion, 'k': 0, 'stops': <String, dynamic>{}, 'inside': null, 'exit_count': 0,
      'away': <String, dynamic>{'count': 0, 'last_d': null}, 'revisit': null, 'last_fix': null, 'speed_ema': null, 'fixes': 0,
    };

Map<String, dynamic> _rec(Map<String, dynamic> st, Map stop) {
  final stops = st['stops'] as Map<String, dynamic>;
  return stops.putIfAbsent(stop['id'] as String, () => <String, dynamic>{
        'status': null, 'closest_m': null, 'closest_at': null, 'entered_at': null, 'last_inside_at': null,
        'min_speed': null, 'arrived': false, 'decided_at': null, 'near_since': null, 'near_dwell_s': 0.0, 'near_m': null,
      }) as Map<String, dynamic>;
}

String _name(Map stop) => (stop['name'] as String?) ?? 'stop ${stop['stop_order']}';

Map<String, dynamic> _decision(String type, Map? stop, DateTime at, String message, [Map<String, dynamic>? payload]) {
  final d = <String, dynamic>{'type': type, 'at': _iso(at), 'message': message, 'payload': payload ?? {}};
  if (stop != null) {
    d['stop_id'] = stop['id'];
    d['stop_order'] = stop['stop_order'];
    d['stop_name'] = stop['name'];
  }
  return d;
}

Map<String, dynamic> _visit(Map stop, String status, Map rec, String? arrival, [String? departure]) => {
      'type': 'visit', 'stop_id': stop['id'], 'stop_order': stop['stop_order'], 'status': status,
      'arrival_time': arrival, 'departure_time': departure, 'closest_m': _r1(rec['closest_m'] as num?),
    };

Map<String, dynamic> _nextChanged(List<Map> stops, Map<String, dynamic> st, DateTime at, String why) {
  final k = st['k'] as int;
  final nxt = k < stops.length ? stops[k] : null;
  final msg = (nxt != null ? 'next stop is now ${_name(nxt)} (#${nxt['stop_order']})' : 'all stops done') + ' — $why';
  return _decision('next_stop_changed', nxt, at, msg, {'next_index': k, 'reason': why});
}

double? _dwell(Map rec) {
  if (rec['entered_at'] != null && rec['last_inside_at'] != null) {
    return _r1(_secs(_parse(rec['last_inside_at']), _parse(rec['entered_at'])));
  }
  return null;
}

bool _stopped(Map rec, Map<String, double> cfg) {
  final d = _dwell(rec);
  final ms = rec['min_speed'] as num?;
  return (d != null && d >= cfg['stop_dwell_s']!) || (ms != null && ms <= cfg['stopped_mps']!);
}

List<Map<String, dynamic>> _closeStop(Map<String, dynamic> st, List<Map> stops, int i, DateTime at, Map<String, double> cfg, String why) {
  final s = stops[i];
  final rec = _rec(st, s);
  final out = <Map<String, dynamic>>[];
  final closest = (rec['closest_m'] as num?)?.toDouble();
  final nearDwell = ((rec['near_dwell_s'] as num?) ?? 0).toDouble();
  if (rec['arrived'] == true) {
    rec['status'] = 'visited';
    out.add(_decision('stop_departed', s, at, 'left ${_name(s)}',
        {'arrival': rec['entered_at'], 'departure': rec['last_inside_at'], 'dwell_s': _dwell(rec)}));
    out.add(_visit(s, 'visited', rec, rec['entered_at'], rec['last_inside_at']));
  } else if ((closest == null || closest > cfg['arrive_radius_m']!) && nearDwell >= cfg['near_dwell_s']!) {
    rec['status'] = 'visited';
    final nearM = (rec['near_m'] as num?) ?? closest ?? 0;
    out.add(_decision('stop_arrived', s, at,
        'arrived near ${_name(s)}: waited ${(nearDwell / 60).toStringAsFixed(1)} min about ${nearM.round()} m from the stop pin (pin may be misplaced)',
        {'near': true, 'near_dwell_s': _r1(nearDwell), 'near_m': _r1(rec['near_m'] as num?), 'closest_m': _r1(closest), 'reason': why}));
    out.add(_visit(s, 'visited', rec, (rec['closest_at'] as String?) ?? _iso(at)));
  } else if (closest != null && closest <= cfg['pass_radius_m']!) {
    rec['status'] = 'passed';
    out.add(_decision('stop_passed', s, at, 'passed ~${closest.round()} m from ${_name(s)} without stopping',
        {'closest_m': _r1(closest), 'closest_at': rec['closest_at'], 'reason': why, 'min_speed_mps': _r1(rec['min_speed'] as num?)}));
    out.add(_visit(s, 'passed', rec, (rec['closest_at'] as String?) ?? _iso(at)));
  } else {
    rec['status'] = 'skipped';
    final far = closest != null ? 'closest approach ${closest.round()} m' : 'never approached';
    out.add(_decision('stop_skipped', s, at, 'skipped ${_name(s)}: $far, $why',
        {'closest_m': _r1(closest), 'closest_at': rec['closest_at'], 'reason': why}));
    out.add(_visit(s, 'skipped', rec, (rec['closest_at'] as String?) ?? _iso(at)));
  }
  rec['decided_at'] = _iso(at);
  if (st['inside'] == s['id']) st['inside'] = null;
  st['exit_count'] = 0;
  st['away'] = <String, dynamic>{'count': 0, 'last_d': null};
  if (st['k'] == i) st['k'] = i + 1;
  return out;
}

void _trackNear(Map rec, double d, DateTime t, double? speed, Map<String, double> cfg) {
  final slow = speed != null && speed <= cfg['near_moving_mps']!;
  if (d <= cfg['near_radius_m']! && slow) {
    if (rec['near_since'] == null) {
      rec['near_since'] = _iso(t);
      rec['near_m'] = d;
    } else {
      final nm = (rec['near_m'] as num?)?.toDouble();
      rec['near_m'] = math.min((nm == null || nm == 0) ? d : nm, d);
    }
    final dwell = _secs(t, _parse(rec['near_since']));
    rec['near_dwell_s'] = math.max(((rec['near_dwell_s'] as num?) ?? 0).toDouble(), dwell);
  } else {
    rec['near_since'] = null;
  }
}

List<Map<String, dynamic>> _enter(Map<String, dynamic> st, List<Map> stops, int i, DateTime at, double d, double? speed, Map<String, double> cfg) {
  final s = stops[i];
  final rec = _rec(st, s);
  st['inside'] = s['id'];
  st['exit_count'] = 0;
  rec['entered_at'] = _iso(at);
  rec['last_inside_at'] = _iso(at);
  rec['min_speed'] = speed;
  final out = <Map<String, dynamic>>[
    _decision('stop_entered', s, at, 'entered ${_name(s)} radius (${d.round()} m)',
        {'distance_m': _r1(d), 'radius_m': cfg['arrive_radius_m'], 'speed_mps': _r1(speed)})
  ];
  if (speed != null && speed <= cfg['stopped_mps']!) {
    rec['arrived'] = true;
    rec['status'] = 'visited';
    out.add(_decision('stop_arrived', s, at, 'arrived at ${_name(s)}',
        {'arrival': rec['entered_at'], 'distance_m': _r1(d), 'min_speed_mps': _r1(speed)}));
    out.add(_visit(s, 'visited', rec, rec['entered_at']));
  }
  return out;
}

List<Map<String, dynamic>> _revisits(Map<String, dynamic> st, List<Map> stops, Map p, DateTime t, double? speed, Map<String, double> cfg) {
  final out = <Map<String, dynamic>>[];
  final r = cfg['arrive_radius_m']!;
  final byId = {for (final s in stops) s['id']: s};
  final rv = st['revisit'] as Map<String, dynamic>?;
  if (rv != null && byId.containsKey(rv['stop_id'])) {
    final s = byId[rv['stop_id']]!;
    final rec = _rec(st, s);
    final d = haversineM(p['lat'], p['lng'], (s['lat'] as num).toDouble(), (s['lng'] as num).toDouble());
    if (d <= r + cfg['exit_hysteresis_m']!) {
      if (speed != null) {
        final ms = rv['min_speed'] as num?;
        rv['min_speed'] = ms == null ? speed : math.min(ms.toDouble(), speed);
      }
      final dwell = _secs(t, _parse(rv['entered_at']));
      final ms = rv['min_speed'] as num?;
      if (rec['status'] == 'passed' && (dwell >= cfg['stop_dwell_s']! || (ms != null && ms <= cfg['stopped_mps']!))) {
        rec['status'] = 'visited';
        out.add(_decision('stop_upgraded', s, t, 'stopped at ${_name(s)} on a later pass — now visited',
            {'distance_m': _r1(d), 'was': 'passed', 'now': 'visited', 'dwell_s': _r1(dwell)}));
        out.add(_visit(s, 'visited', rec, rv['entered_at'], _iso(t)));
      }
      return out;
    }
    st['revisit'] = null;
  }
  final upto = math.min(st['k'] as int, stops.length);
  for (var i = 0; i < upto; i++) {
    final s = stops[i];
    final rec = _rec(st, s);
    if (rec['status'] == null) continue;
    final d = haversineM(p['lat'], p['lng'], (s['lat'] as num).toDouble(), (s['lng'] as num).toDouble());
    if (d > r) continue;
    st['revisit'] = <String, dynamic>{'stop_id': s['id'], 'entered_at': _iso(t), 'min_speed': speed};
    if (rec['status'] == 'skipped') {
      rec['status'] = 'passed';
      final c = rec['closest_m'] as num?;
      rec['closest_m'] = c == null ? d : math.min(c.toDouble(), d);
      out.add(_decision('stop_upgraded', s, t, 'reached ${_name(s)} after it was skipped — now passed',
          {'distance_m': _r1(d), 'was': 'skipped', 'now': 'passed'}));
      out.add(_visit(s, 'passed', rec, _iso(t)));
    } else {
      out.add(_decision('stop_reentered', s, t, 'back at ${_name(s)} (already ${rec['status']})', {'distance_m': _r1(d)}));
    }
    return out;
  }
  return out;
}

/// Feed one ACCEPTED fix {lat, lng, recorded_at, speed?}. Returns the decisions;
/// `state` is updated in place. Decisions of type 'visit' are stop-visit
/// upserts, the rest are decision-log events (send them with the app event batch).
List<Map<String, dynamic>> stepProgress(Map<String, dynamic> st, List<Map> stops, Map fix, [Map<String, double>? config]) {
  final cfg = config ?? stopProgressConfig();
  final out = <Map<String, dynamic>>[];
  if (stops.isEmpty) return out;
  final t = _parse(fix['recorded_at']);
  final p = {'lat': (fix['lat'] as num).toDouble(), 'lng': (fix['lng'] as num).toDouble()};
  final prev = st['last_fix'] as Map<String, dynamic>?;
  if (prev != null && !t.isAfter(_parse(prev['t']))) {
    return [_decision('fix_out_of_order', null, t, 'fix older than the last one used — ignored for stop progress',
        {'fix_at': _iso(t), 'last_at': prev['t']})];
  }
  final dt = prev != null ? _secs(t, _parse(prev['t'])) : null;
  final interp = prev != null && dt != null && dt <= cfg['max_interp_gap_s']!;
  final segA = interp ? {'lat': prev['lat'], 'lng': prev['lng']} : p;
  double? speed = (fix['speed'] as num?)?.toDouble();
  if (speed == null || speed.isNaN || speed < 0) {
    speed = (prev != null && dt != null && dt != 0) ? haversineM(prev['lat'], prev['lng'], p['lat']!, p['lng']!) / dt : null;
  }
  if (speed != null) {
    final ema = (st['speed_ema'] as num?)?.toDouble();
    st['speed_ema'] = ema == null ? speed : 0.7 * ema + 0.3 * speed;
  }
  st['last_fix'] = <String, dynamic>{'lat': p['lat'], 'lng': p['lng'], 't': _iso(t), 'speed': _r1(speed)};
  st['fixes'] = ((st['fixes'] as int?) ?? 0) + 1;

  final n = stops.length;
  final k = st['k'] as int;
  final r = cfg['arrive_radius_m']!;
  final tPrev = prev != null ? _parse(prev['t']) : t;
  final segD = <int, List<Object>>{};
  final endD = <int, double>{};
  final hi = math.min(n, k + 1 + cfg['lookahead']!.toInt());
  for (var i = k; i < hi; i++) {
    final cs = closestOnSegment(segA, p, stops[i]);
    final at = interp ? tPrev.add(Duration(microseconds: (t.difference(tPrev).inMicroseconds * cs[1]).round())) : t;
    segD[i] = [cs[0], at];
    endD[i] = haversineM(p['lat']!, p['lng']!, (stops[i]['lat'] as num).toDouble(), (stops[i]['lng'] as num).toDouble());
    final rec = _rec(st, stops[i]);
    final c = rec['closest_m'] as num?;
    if (c == null || cs[0] < c) {
      rec['closest_m'] = cs[0];
      rec['closest_at'] = _iso(at);
    }
    _trackNear(rec, endD[i]!, t, speed, cfg);
  }

  if (k >= n) {
    out.addAll(_revisits(st, stops, p, t, speed, cfg));
    return out;
  }

  final inside = st['inside'];
  if (inside != null && inside == stops[k]['id']) {
    final rec = _rec(st, stops[k]);
    if (k + 1 < n && (endD[k + 1] ?? 1e18) <= r && endD[k + 1]! < endD[k]!) {
      out.addAll(_closeStop(st, stops, k, t, cfg, 'reached the next stop ${_name(stops[k + 1])} right after it'));
      out.add(_nextChanged(stops, st, t, 'stops close together'));
      out.addAll(_enter(st, stops, k + 1, t, endD[k + 1]!, speed, cfg));
      return out;
    }
    if (endD[k]! <= r + cfg['exit_hysteresis_m']!) {
      st['exit_count'] = 0;
      if (endD[k]! <= r) {
        rec['last_inside_at'] = _iso(t);
        if (speed != null) {
          final ms = rec['min_speed'] as num?;
          rec['min_speed'] = ms == null ? speed : math.min(ms.toDouble(), speed);
        }
      }
      if (rec['arrived'] != true && _stopped(rec, cfg)) {
        rec['arrived'] = true;
        rec['status'] = 'visited';
        out.add(_decision('stop_arrived', stops[k], t, 'arrived at ${_name(stops[k])}',
            {'arrival': rec['entered_at'], 'distance_m': _r1(endD[k]), 'dwell_s': _dwell(rec), 'min_speed_mps': _r1(rec['min_speed'] as num?)}));
        out.add(_visit(stops[k], 'visited', rec, rec['entered_at']));
      }
      return out;
    }
    st['exit_count'] = ((st['exit_count'] as int?) ?? 0) + 1;
    if ((st['exit_count'] as int) < cfg['exit_fixes']!.toInt()) return out;
    out.addAll(_closeStop(st, stops, k, t, cfg, 'left the stop radius'));
    out.add(_nextChanged(stops, st, t, 'left ${_name(stops[k])}'));
    return out;
  }

  int? target;
  final away = st['away'] as Map<String, dynamic>;
  if ((segD[k]![0] as double) <= r) {
    target = k;
  } else {
    final lastD = (away['last_d'] as num?)?.toDouble();
    final movingAway = lastD != null && endD[k]! > lastD + 5.0;
    final ck = (_rec(st, stops[k])['closest_m'] as num?)?.toDouble();
    final wentBy = ck != null && ck <= cfg['pass_radius_m']!;
    for (var j = k + 1; j < hi; j++) {
      if ((segD[j]![0] as double) <= r && (wentBy || movingAway) && endD[j]! < endD[k]!) {
        target = j;
        break;
      }
    }
  }
  if (target != null) {
    for (var i = k; i < target; i++) {
      out.addAll(_closeStop(st, stops, i, t, cfg, 'bus reached ${_name(stops[target])} first'));
    }
    if (target > k) out.add(_nextChanged(stops, st, t, 'reached ${_name(stops[target])}'));
    st['k'] = target;
    out.addAll(_enter(st, stops, target, segD[target]![1] as DateTime, endD[target]!, speed, cfg));
    if (st['inside'] == stops[target]['id'] && endD[target]! > r + cfg['exit_hysteresis_m']!) {
      out.addAll(_closeStop(st, stops, target, t, cfg, 'drove through the stop radius between two fixes'));
      out.add(_nextChanged(stops, st, t, 'passed ${_name(stops[target])}'));
    }
    return out;
  }

  final away2 = st['away'] as Map<String, dynamic>;
  if (k + 1 < n) {
    final rec = _rec(st, stops[k]);
    final dNext = endD[k + 1] ??
        haversineM(p['lat']!, p['lng']!, (stops[k + 1]['lat'] as num).toDouble(), (stops[k + 1]['lng'] as num).toDouble());
    final beyond = dNext <
        haversineM((stops[k]['lat'] as num).toDouble(), (stops[k]['lng'] as num).toDouble(),
            (stops[k + 1]['lat'] as num).toDouble(), (stops[k + 1]['lng'] as num).toDouble());
    final lastD = (away2['last_d'] as num?)?.toDouble();
    final farther = lastD == null || endD[k]! >= lastD - 10.0;
    final c = (rec['closest_m'] as num?)?.toDouble();
    if (beyond && farther && c != null && endD[k]! >= c + cfg['away_m']!) {
      away2['count'] = (away2['count'] as int) + 1;
    } else {
      away2['count'] = 0;
    }
    away2['last_d'] = endD[k];
    if ((away2['count'] as int) >= cfg['away_fixes']!.toInt()) {
      out.addAll(_closeStop(st, stops, k, t, cfg, 'bus moved on toward ${_name(stops[k + 1])}'));
      out.add(_nextChanged(stops, st, t, 'moved past ${_name(stops[k])}'));
      return out;
    }
  } else {
    away2['last_d'] = endD[k];
  }
  out.addAll(_revisits(st, stops, p, t, speed, cfg));
  return out;
}

/// Trip ended: close the stop the bus is at; every stop never reached is
/// SKIPPED with its closest approach. Idempotent.
List<Map<String, dynamic>> finalizeProgress(Map<String, dynamic> st, List<Map> stops, Object at, [Map<String, double>? config]) {
  final cfg = config ?? stopProgressConfig();
  final t = _parse(at);
  final out = <Map<String, dynamic>>[];
  while ((st['k'] as int) < stops.length) {
    final i = st['k'] as int;
    final atStop = st['inside'] == stops[i]['id'];
    out.addAll(_closeStop(st, stops, i, t, cfg, atStop ? 'trip ended at this stop' : 'trip ended before reaching it'));
  }
  st['inside'] = null;
  return out;
}

/// Next stop, ETA and progress for the UI.
Map<String, dynamic> progressSummary(Map<String, dynamic> st, List<Map> stops, [Map<String, double>? config]) {
  final cfg = config ?? stopProgressConfig();
  final n = stops.length;
  final k = math.min((st['k'] as int?) ?? 0, n);
  var done = 0, skipped = 0;
  final rows = <Map<String, dynamic>>[];
  for (final s in stops) {
    final rec = ((st['stops'] as Map)[s['id']] as Map?) ?? const {};
    final status = rec['status'];
    if (status == 'visited' || status == 'passed') done++;
    if (status == 'skipped') skipped++;
    rows.add({'stop_id': s['id'], 'stop_order': s['stop_order'], 'name': s['name'], 'status': status,
      'closest_m': _r1(rec['closest_m'] as num?)});
  }
  Map<String, dynamic>? nxt;
  final lf = st['last_fix'] as Map?;
  if (k < n) {
    final s = stops[k];
    final dist = lf == null ? null : haversineM(lf['lat'], lf['lng'], (s['lat'] as num).toDouble(), (s['lng'] as num).toDouble());
    final sp = (st['speed_ema'] as num?)?.toDouble() ?? 0.0;
    final eta = dist == null ? null : (dist * cfg['road_factor']! / math.max(sp, cfg['min_eta_speed_mps']!)).round();
    nxt = {'stop_id': s['id'], 'stop_order': s['stop_order'], 'name': s['name'], 'distance_m': _r1(dist), 'eta_s': eta,
      'at_stop': st['inside'] == s['id']};
  }
  return {
    'next_stop': nxt, 'next_index': k, 'total': n, 'done': done, 'skipped': skipped,
    'progress_pct': n == 0 ? 0.0 : (1000.0 * (done + skipped) / n).round() / 10.0,
    'stops': rows, 'last_fix_at': lf?['t'], 'arrive_radius_m': cfg['arrive_radius_m'],
  };
}
